\njeepney                  0.8.0\\nJinja2                   3.1.2\\njmespath                 1.0.1\\njsonpatch                1.32\\njsonpointer              2.0\\njsonschema               4.10.3\\nkeyring                  24.3.1\\nlanguage-selector        0.1\\nlaunchpadlib             1.11.0\\nlazr.restfulclient       0.14.6\\nlazr.uri                 1.0.6\\nlouis                    3.29.0\\nMako                     1.3.2.dev0\\nMarkdown                 3.5.2\\nmarkdown-it-py           3.0.0\\nMarkupSafe               2.1.5\\nmdurl                    0.1.2\\nmechanize                0.4.9\\nmonotonic                1.6\\nmore-itertools           10.2.0\\nnetaddr                  0.8.0\\nnetifaces                0.11.0\\noauth2client             4.1.3\\noauthlib                 3.2.2\\nolefile                  0.46\\npackaging                24.0\\nparamiko                 2.12.0\\npathlib                  1.0.1\\npbr                      5.11.1\\npexpect                  4.9.0\\npillow                   10.2.0\\npip                      24.0\\nprotobuf                 6.32.1\\nptyprocess               0.7.0\\npyasn1                   0.4.8\\npyasn1-modules           0.2.8\\npycairo                  1.25.1\\npycups                   2.0.1\\nPyDrive                  1.3.1\\nPygments                 2.17.2\\nPyGObject                3.48.2\\nPyJWT                    2.7.0\\nPyNaCl                   1.5.0\\npyOpenSSL                23.2.0\\npyparsing                3.1.1\\npyrsistent               0.20.0\\npyscard                  2.0.7\\npyserial                 3.5\\npython-apt               2.7.7+ubuntu5.1\\npython-dateutil          2.8.2\\npython-debian            0.1.49+ubuntu2\\npython-xlib              0.33\\npytz                     2024.1\\npyxdg                    0.28\\nPyYAML                   6.0.1\\nrequests                 2.31.0\\nrequests-oauthlib        2.0.0\\nrich                     13.7.1\\nrsa                      4.9\\ns3transfer              